    "id": "decreto-43-2023-art-65",
    "docId": "decreto-43-2023",
    "docTitle": "Decreto n.º 43/2023 — Regulamento de Licenciamento das IES",
    "number": 65,
    "title": "Descontinuidade de programas ou cursos",
